<section id="history" class="relative isolate overflow-hidden border-y border-ringside-line bg-ringside-surface-deep py-[clamp(4rem,7vw,7rem)]" aria-labelledby="history-title">
    <img class="absolute inset-0 -z-10 h-full w-full object-cover object-[center_52%] max-[767px]:h-[62%] max-[767px]:object-[72%_44%]" src="images/marketing/match-result.webp" srcset="images/marketing/match-result-960.webp 960w, images/marketing/match-result.webp 1672w" sizes="100vw" width="1672" height="941" alt="" aria-hidden="true" loading="lazy">
    <div class="absolute inset-0 -z-10 bg-scrim-right max-[767px]:bg-scrim-fade" aria-hidden="true"></div>
    <x-page-width class="relative">
        <div class="max-w-[46rem]">
            <x-display-heading tag="h2" id="history-title" class="max-w-[16ch] text-[clamp(2.5rem,4.2vw,3.75rem)]">A result should carry the whole story.</x-display-heading>
            <p class="mt-6 max-w-[42rem] text-[1.1rem] leading-[1.7] text-ringside-muted">Connect the match you booked to how it ended, then keep that record with the championship.</p>
            <ol class="mt-10 border-t border-ringside-line" aria-label="From booking to title history">
                <li class="grid grid-cols-[9rem_1fr] gap-5 border-b border-ringside-line py-5 max-[767px]:grid-cols-1 max-[767px]:gap-2">
                    <span class="text-xs font-bold uppercase tracking-[0.08em] text-ringside-signal">Booked</span>
                    <div><h3 class="font-bold">The match card</h3><p class="mt-1 text-sm leading-relaxed text-ringside-muted">Competitors, referee and title on one match.</p></div>
                </li>
                <li class="grid grid-cols-[9rem_1fr] gap-5 border-b border-ringside-line py-5 max-[767px]:grid-cols-1 max-[767px]:gap-2">
                    <span class="text-xs font-bold uppercase tracking-[0.08em] text-ringside-signal">Result</span>
                    <div><h3 class="font-bold">How it ended</h3><p class="mt-1 text-sm leading-relaxed text-ringside-muted">Record the winner and the finish: pinfall, submission, count-out, disqualification and more.</p></div>
                </li>
                <li class="grid grid-cols-[9rem_1fr] gap-5 border-b border-ringside-line py-5 max-[767px]:grid-cols-1 max-[767px]:gap-2">
                    <span class="text-xs font-bold uppercase tracking-[0.08em] text-ringside-signal">Title record</span>
                    <div><h3 class="font-bold">The championship’s history</h3><p class="mt-1 text-sm leading-relaxed text-ringside-muted">Every reign stays on the championship’s history, not in someone’s memory.</p></div>
                </li>
            </ol>
        </div>
    </x-page-width>
</section>
